use chrono::{DateTime, Utc};

/// The concrete sellable unit: a product with one selection per variant.
///
/// `selection_key` is the deterministic identity used to diff a regenerated
/// catalog. SKUs are generated by the application, never authored directly.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct ProductSku {
    pub id: i64,
    pub product_id: i64,
    pub selection_key: String,
    pub code: Option<String>,
    pub created_at: DateTime<Utc>,
    pub updated_at: Option<DateTime<Utc>>,
    pub created_by: Option<i64>,
    pub updated_by: Option<i64>,
}
